INSERT INTO questions (id, examId, specialty, difficulty, question, optionA, optionB, optionC, optionD, optionE, correctAnswer, explanationCorrect, createdAt, updatedAt) VALUES
(720100, 1, 'Ophthalmology', 'Hard', 'A 68-year-old man with type 2 diabetes presents with gradual painless vision loss in both eyes. Fundoscopy reveals hard exudates in a circinate pattern around the macula with retinal thickening. Which of the following is the most appropriate initial management?', 'Tight glycaemic control and monitoring with OCT imaging every 4 weeks', 'Intravitreal bevacizumab injection', 'Referral for cataract surgery', 'Vitrectomy', 'Immediate laser photocoagulation to all areas of exudates', 'A', 'Diabetic macular oedema (DMO) with hard exudates is managed initially with glycaemic control and monitoring. Laser is reserved for cases with central involvement and visual threat. Further reading: NICE CKS on Diabetic Retinopathy.', NOW(), NOW()),
(720101, 1, 'Ophthalmology', 'Hard', 'A 45-year-old woman on hydroxychloroquine for SLE develops blurred central vision and colour vision defects. Visual acuity is 6/9 in both eyes. OCT shows parafoveal thinning of the inner nuclear layer. What is the most appropriate next step?', 'Discontinue hydroxychloroquine immediately', 'Perform visual field testing and repeat OCT in 3 months', 'Switch to chloroquine', 'Refer for retinal specialist assessment for possible retinal toxicity', 'Continue hydroxychloroquine with 6-monthly ophthalmology review', 'D', 'Hydroxychloroquine retinopathy is rare but serious. OCT changes with colour vision defects warrant specialist assessment to determine if retinal toxicity has developed. Further reading: Ophthalmology guidelines on antimalarial toxicity.', NOW(), NOW()),
(720102, 1, 'Ophthalmology', 'Hard', 'A 72-year-old man with acute angle-closure glaucoma presents with corneal oedema, mid-dilated pupil, and IOP of 58 mmHg. After initial medical management, gonioscopy reveals peripheral anterior synechiae in 4 quadrants. Which of the following is the most appropriate definitive treatment?', 'Gonioplasty', 'Anterior vitrectomy', 'Laser peripheral iridotomy', 'Cyclophotocoagulation', 'Trabeculectomy', 'E', 'Extensive peripheral anterior synechiae (PAS) indicate chronic angle closure. Iridotomy alone may not restore angle patency. Trabeculectomy is indicated for IOP control when PAS is extensive. Further reading: Glaucoma management guidelines.', NOW(), NOW()),
(720103, 1, 'Ophthalmology', 'Hard', 'A 55-year-old woman with myopia of -8.00 DS presents with sudden floaters and flashing lights. Dilated fundoscopy shows a retinal break with subretinal fluid extending to the macula. Best corrected visual acuity is 6/12. What is the most appropriate management?', 'Laser retinopexy', 'Scleral buckle', 'Pneumatic retinopexy', 'Pars plana vitrectomy', 'Observation with weekly review', 'D', 'Macula-off retinal detachment requires urgent surgery within 72 hours. Vitrectomy is preferred for high myopia with macular involvement. Further reading: Retinal detachment management protocols.', NOW(), NOW()),
(720104, 1, 'Ophthalmology', 'Hard', 'A 38-year-old man with neurofibromatosis type 1 presents with progressive visual field loss and decreased colour vision. MRI shows optic pathway glioma with 30% enlargement over 2 years. Visual acuity is 6/6 bilaterally. What is the most appropriate management?', 'Intrathecal chemotherapy', 'Observation with 6-monthly MRI and visual assessment', 'Radiotherapy to optic pathways', 'Surgical debulking', 'Immediate chemotherapy', 'B', 'Optic pathway gliomas in NF1 are often indolent. Treatment is reserved for symptomatic or rapidly progressive cases. Observation with imaging surveillance is appropriate when vision is preserved. Further reading: NF1 management guidelines.', NOW(), NOW()),
(720105, 1, 'Ophthalmology', 'Hard', 'A 42-year-old woman with Graves'' disease develops diplopia and restricted upgaze. Hess chart shows restrictive pattern. What is the most appropriate initial management?', 'Immediate orbital decompression', 'High-dose intravenous methylprednisolone followed by oral prednisolone taper', 'Thyroid ablation', 'Prism glasses for diplopia', 'Botulinum toxin injection', 'B', 'Thyroid eye disease with restrictive pattern and diplopia indicates active inflammation. IV methylprednisolone is first-line for active disease. Further reading: Thyroid eye disease management.', NOW(), NOW()),
(720106, 1, 'Ophthalmology', 'Hard', 'A 65-year-old man with primary open-angle glaucoma on maximum tolerated medical therapy has IOP of 22 mmHg with progressive optic disc cupping and visual field loss. Gonioscopy shows open angles with trabecular meshwork visible to Schwalbe''s line. What is the most appropriate next step?', 'Add another topical agent', 'Laser trabeculoplasty', 'Trabeculectomy', 'Cyclophotocoagulation', 'Tube shunt implantation', 'B', 'Selective laser trabeculoplasty is indicated for open-angle glaucoma inadequately controlled on medical therapy before considering surgery. Further reading: Glaucoma treatment algorithms.', NOW(), NOW()),
(720107, 1, 'Ophthalmology', 'Hard', 'A 28-year-old woman with history of herpes simplex keratitis presents with recurrent episodes. She is planning pregnancy. Which of the following is the most appropriate prophylactic strategy?', 'Topical aciclovir 5 times daily indefinitely', 'Oral aciclovir 400 mg twice daily during pregnancy', 'No prophylaxis needed', 'Topical interferon-alpha', 'Topical povidone-iodine', 'B', 'Oral aciclovir prophylaxis reduces recurrence risk during pregnancy and labour. Further reading: Herpes simplex keratitis management in pregnancy.', NOW(), NOW()),
(720108, 1, 'Ophthalmology', 'Hard', 'A 51-year-old man with branch retinal artery occlusion and cotton-wool spots presents with sudden visual field loss. Carotid ultrasound shows 70% stenosis. Blood pressure is 165/95 mmHg. What is the most appropriate management?', 'Aspirin 75 mg daily only', 'Carotid endarterectomy', 'Carotid stenting', 'Intensive blood pressure control and aspirin', 'Warfarin anticoagulation', 'D', 'BRVO with carotid stenosis <80% is managed medically. Intensive BP control and antiplatelet therapy are indicated. Further reading: Retinal artery occlusion guidelines.', NOW(), NOW()),
(720109, 1, 'Ophthalmology', 'Hard', 'A 60-year-old woman with age-related macular degeneration and choroidal neovascularization shows poor response to 3 monthly intravitreal ranibizumab injections. OCT shows persistent subretinal fluid. What is the most appropriate next step?', 'Continue ranibizumab monthly', 'Switch to aflibercept', 'Add photodynamic therapy', 'Perform thermal laser', 'Observe without treatment', 'B', 'Poor response to ranibizumab may indicate need for switch to alternative anti-VEGF agent. Aflibercept has longer half-life and may be more effective. Further reading: AMD treatment guidelines.', NOW(), NOW());
